:root {
  color-scheme: light;
  font-family: Arial, Helvetica, sans-serif;
  color: #17202a;
  background: #f5f7fa;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

button {
  font: inherit;
}

.catalog-page {
  min-height: 100vh;
  padding: 64px 24px;
}

.catalog-shell {
  max-width: 1080px;
  margin: 0 auto;
}

.catalog-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
}

.eyebrow {
  margin: 0 0 12px;
  color: #637185;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: clamp(32px, 5vw, 42px);
  letter-spacing: -0.04em;
}

.catalog-description {
  margin: 12px 0 0;
  color: #637185;
  line-height: 1.5;
}

.sync-button {
  min-height: 42px;
  padding: 0 18px;
  border: 1px solid #174bb8;
  border-radius: 8px;
  background: #235bd3;
  color: white;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.sync-button:hover {
  background: #174bb8;
}

.sync-button:focus-visible {
  outline: 3px solid #8db3ff;
  outline-offset: 3px;
}

